tems:center;padding:35px 0 27px}.side-panel{height:600px;display:flex;flex-direction:column}.section-label{font-size:9px;letter-spacing:.15em;color:#838795}.left-panel h1{font-size:35px;line-height:1.04;letter-spacing:-.06em;margin:19px 0 12px;font-weight:600}.left-panel h1 span{color:var(--lime)}.intro-copy{font-size:12px;line-height:1.65;color:#999cab;max-width:180px;margin:0 0 27px}.mission-card{background:rgba(24,27,40,.83);border:1px solid #292d3d;border-radius:8px;padding:15px 13px 10px}.card-heading{font-size:9px;color:#c3c4cb;letter-spacing:.1em;margin-bottom:12px}.tiny-spark{color:var(--lime);font-size:14px;margin-right:5px}.power-row{display:flex;align-items:center;gap:10px;padding:8px 0;border-top:1px solid rgba(255,255,255,.05)}.power-icon{width:25px;height:25px;display:grid;place-items:center;border-radius:6px;font-size:16px;font-weight:700}.power-icon.widen{color:var(--lime);background:rgba(212,252,87,.12)}.power-icon.multi{color:var(--cyan);background:rgba(110,230,255,.12)}.power-icon.fire{color:#ff9971;background:rgba(255,153,113,.12)}.power-icon.ghost{color:var(--violet);background:rgba(167,150,255,.13)}.power-row b{display:block;font-size:8px;letter-spacing:.07em;color:#e4e4e6}.power-row small{display:block;font-size:9px;color:#818493;margin-top:3px}.tip{display:flex;gap:10px;margin-top:auto;padding:12px 10px;border-top:1px solid #2a2d3a;color:#9396a4;font-size:10px;line-height:1.55}.tip b{color:#dfe0e3;font-weight:500}.tip-star{font-size:18px;color:var(--lime)}.arcade{width:100%;max-width:800px}.arcade-top{height:65px;background:#171a27;border:1px solid #2a2d3b;border-bottom:0;border-radius:9px 9px 0 0;display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;padding:0 25px}.stat-block{display:flex;flex-direction:column;gap:5px}.stat-block.centered{align-items:center}.stat-block.right{align-items:flex-end}.stat-label{font-size:8px;letter-spacing:.15em;color:#858998}.stat-block strong{font-family:'DM Mono',monospace;font-size:17px;font-weight:500;letter-spacing:.08em}.stat-block strong small{font-size:10px;color:#727685}.hearts{font-size:13px!important;letter-spacing:3px!important;color:var(--pink)}.canvas-wrap{position:relative;width:100%;aspect-ratio:4/3;background:#111522;border:1px solid #2b2e3c;overflow:hidden}canvas{display:block;width:100%;height:100%;touch-action:none}.screen-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden;background:rgba(13,16,27,.42);transition:opacity .35s,visibility .35s}.screen-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-content{position:relative;z-index:2;text-align:center;margin-top:-3px}.overlay-kicker{font-size:9px;letter-spacing:.13em;color:#c5c6ce}.overlay-kicker .live-dot{width:6px;height:6px}.overlay-content h2{font-size:clamp(39px,5vw,58px);letter-spacing:-.075em;line-height:.98;margin:18px 0 13px;font-weight:600}.overlay-content h2 em{font-style:normal;color:var(--lime)}.overlay-content p{font-size:12px;line-height:1.7;color:#a6a8b5;margin:0 0 23px}.play-button{background:var(--lime);color:#171a22;border:0;border-radius:4px;padding:14px 18px;font:700 10px 'DM Mono',monospace;letter-spacing:.08em;min-width:174px;cursor:pointer;display:inline-flex;align-items:center;justify-content:space-between;gap:28px;box-shadow:0 0 25px rgba(212,252,87,.13);transition:transform .2s,box-shadow .2s}.play-button:hover{transform:translateY(-2px);box-shadow:0 6px 26px rgba(212,252,87,.24)}.button-arrow{font-size:16px}.overlay-hint{margin-top:17px;font-size:8px;color:#878a98;letter-spacing:.1em}kbd{font:inherit;color:#dcdee4;border:1px solid #4a4e5e;padding:3px 5px;border-radius:3px;margin:0 3px}.overlay-orbit{position:absolute;width:420px;height:420px;border-radius:50%;border:1px solid rgba(198,217,105,.09);pointer-events:none}.orbit-one{left:-215px;top:-210px}.orbit-two{right:-275px;bottom:-260px;width:560px;height:560px;border-color:rgba(136,157,255,.09)}.level-toast{position:absolute;left:50%;top:38%;transform:translate(-50%,-50%) scale(.8);font:500 12px 'DM Mono',monospace;letter-spacing:.16em;color:var(--lime);opacity:0;pointer-events:none;text-shadow:0 0 15px var(--lime);transition:.25s}.level-toast.show{opacity:1;transform:translate(-50%,-50%) scale(1)}.arcade-bottom{height:48px;background:#171a27;border:1px solid #2a2d3b;border-top:0;border-radius:0 0 9px 9px;display:flex;align-items:center;justify-content:space-between;padding:0 19px}.controls-hint{display:flex;align-items:center;gap:5px}.keycap{font:10px 'DM Mono',monospace;color:#d4d5dc;background:#252938;border:1px solid #373b4d;border-radius:3px;padding:3px 6px;min-width:19px;text-align:center}.wide-key{font-size:8px;padding:4px 7px}.hint-copy{font-size:8px;letter-spacing:.07em;color:#858997;margin:0 6px 0 2px}.hint-sep{height:15px;border-left:1px solid #383b49;margin:0 7px}.board-coords{font-size:8px;letter-spacing:.08em;color:#777b8a}.coord-dot{color:var(--lime);padding:0 7px}.right-panel{padding-top:2px}.best-score{margin-top:16px;padding:14px 12px;background:rgba(24,27,40,.8);border:1px solid #292d3d;border-radius:7px;display:grid;grid-template-columns:1fr auto;align-items:center;row-gap:7px}.score-label{font-size:8px;color:#8f92a0;letter-spacing:.1em}.best-score strong{grid-column:1/-1;font:500 21px 'DM Mono',monospace;letter-spacing:.1em;color:var(--lime)}.best-badge{grid-column:2;grid-row:1;color:#c3aaff;font:8px 'DM Mono',monospace;letter-spacing:.06em}.progress-block{margin-top:25px}.progress-heading{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.1em;color:#9da0ab}.progress-heading b{color:#f1f0eb;font-size:11px;font-weight:500}.progress-track{height:5px;background:#2c3040;border-radius:4px;margin:10px 0 7px;overflow:hidden}.progress-fill{height:100%;width:0;background:linear-gradient(90deg,var(--lime),#8ee694);box-shadow:0 0 10px rgba(212,252,87,.45);transition:width .3s}.progress-caption{display:flex;justify-content:space-between;font-size:8px;color:#717584;letter-spacing:.07em}.progress-caption span:last-child{color:#bec0c8}.streak-card{display:flex;align-items:center;gap:11px;margin-top:24px;padding:12px;background:rgba(24,27,40,.78);border:1px solid #292d3d;border-radius:7px}.streak-icon{color:#ffb875;font-size:20px}.streak-card strong{display:block;font:500 16px 'DM Mono',monospace;margin-top:5px}.streak-card strong small{font-size:8px;color:#898c99;letter-spacing:.04em}.divider{border-top:1px solid #2b2e3b;margin:25px 0 19px}.howto p{font-size:10px;line-height:1.65;color:#9699a6;margin:11px 0}.touch-hint{font-size:8px;letter-spacing:.05em;color:#777b89;margin-top:13px}.touch-hint span{font-size:16px;color:#b5b7c1;vertical-align:-2px;margin-right:5px}.restart-link{margin-top:auto;align-self:flex-start;border:0;background:none;color:#9194a2;font-size:9px;letter-spacing:.1em;padding:8px 0;cursor:pointer}.restart-link:hover{color:var(--lime)}.restart-link span{font:18px 'Space Grotesk';vertical-align:-2px;margin-right:6px}.footer{height:49px;border-top:1px solid #292c38;display:flex;align-items:center;justify-content:space-between;font-size:8px;letter-spacing:.1em;color:#747887}.footer-center{color:#989ba7}.footer-center span{color:var(--pink);padding-left:5px}.particle-pop{animation:pop .25s ease-out}@keyframes pop{50%{transform:scale(1.13)}}
