cat >/tmp/check-neon.js <<'EOF'
const { chromium } = require('/usr/lib/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/usr/bin/chromium',args:['--no-sandbox']});
 for(const [name,w,h] of [['desktop',1440,900],['phone',390,844]]){
  const page=await browser.newPage({viewport:{width:w,height:h},deviceScaleFactor:1});
  const errors=[]; page.on('console',m=>{if(m.type()==='error') errors.push(m.text())}); page.on('pageerror',e=>errors.push(e.message));
  await page.goto('http://127.0.0.1:3002',{waitUntil:'networkidle'});
  await page.screenshot({path:`screenshots/${name}-check.jpg`,type:'jpeg',quality:82});
  if(name==='desktop'){
   await page.click('#playButton'); await page.waitForTimeout(300);
   await page.keyboard.press('ArrowRight'); await page.waitForTimeout(500); await page.keyboard.up('ArrowRight');
   await page.screenshot({path:'screenshots/playing-check.jpg',type:'jpeg',quality:82});
   console.log(JSON.stringify({name,errors,score:await page.textContent('#score'),status:await page.textContent('#statusText'),bricks:await page.textContent('#brickCount'),overlayHidden:await page.$eval('#overlay',e=>e.classList.contains('hidden'))}));
  }else console.log(JSON.stringify({name,errors,canvas:await page.$eval('#game',e=>({w:e.width,h:e.height,rect:e.getBoundingClientRect().toJSON()})),bodyWidth:await page.evaluate(()=>document.body.scrollWidth)}));
  await page.close();
 }
 await browser.close();
})();
EOF
mkdir -p screenshots
node /tmp/check-neon.js

